fn intersection_size(a: &Set[Int], b: &Set[Int]) -> Int {
  let common = a.intersection(b);
  return common.len();
}

fn all_positive(v: &Vec[Int]) -> Bool {
  var i = 0;
  while i < v.len() {
    if v[i] <= 0 { return false; }
    i = i + 1;
  }
  return true;
}

fn main() -> Int {
  let a = Set[Int]();
  a.insert(1); a.insert(2); a.insert(3);
  let b = Set[Int]();
  b.insert(2); b.insert(3); b.insert(4);
  return intersection_size(&a, &b);
}
